{
"name": "Mara's Batch Deposit",
"hypothesis": "Evidence shows that forcing deposit at 'carrying' (cargo>0) yields 165 stored food, which falls short of the target 224+ (40% gain). Previous attempts failed because agents deposited after every single item, leaving them carrying sub-maximal loads (e.g., cargo=1 or 2) and generating excessive travel costs per unit of food. The solution is to introduce a minimum batch size for the mandatory deposit rule. By changing the condition from 'carrying' to 'carrying>=2', agents will only be forced to return home once they have harvested at least two items, allowing them to fill their capacity to 3 before depositing. This reduces the distance traveled per unit of food harvested, maximizing the energy budget available for gathering and storage within the 720-step limit.",
"rules": [
{
"when": "always",
"do": "explore"
},
{
"when": "foodNear",
"do": "gather"
},
{
"when": "carrying>=2",
"do": "deposit"
},
{
"when": "tired",
"do": "rest"
}
]
}
